using System.Text.Json.Nodes;
using Microsoft.Windows.AI;
using Microsoft.Windows.AI.ContentSafety;
using Microsoft.Windows.AI.Imaging;

namespace AiApp;

// Image captioning (ImageDescriptionGenerator).
//   describeImage { base64, kind? }  kind: detailed (default) | brief | diagram | accessible   -> { text, status }
// Use it for CAPTIONS, never for counting or measuring: there is no on-device object-counting model. Run OCR first and only
// describe images that have little text (the generator answers ImageHasTooMuchText otherwise). Label the result in the UI as
// "generated by on-device AI, may be inaccurate", and tell the language model the caption is what the picture shows.
internal sealed class VisionModule : IBridgeModule
{
    public string Name => "vision";
    public IReadOnlyCollection<string> Ops => new[] { "describeImage" };

    private static ImageDescriptionGenerator? _gen;
    private static readonly SemaphoreSlim Lock = new(1, 1);

    public IEnumerable<(string feature, string state)> Status()
    {
        yield return ("ImageDescriptionGenerator", ImageDescriptionGenerator.GetReadyState().ToString());
    }

    public async Task<JsonObject> HandleAsync(BridgeContext ctx, BridgeRequest req)
    {
        var b64 = req.Str("base64");
        if (string.IsNullOrEmpty(b64)) return R.Fail(req.Id, "No image");

        if (_gen == null)
        {
            await Lock.WaitAsync();
            try
            {
                if (_gen == null)
                {
                    var err = await Ai.EnsureReadyAsync("on-device image description", ImageDescriptionGenerator.GetReadyState,
                        ImageDescriptionGenerator.EnsureReadyAsync, p => ctx.Event(req.Id, "status", $"Preparing image description... {(int)(p * 100)}%"));
                    if (err != null) return R.Fail(req.Id, err);
                    _gen = await ImageDescriptionGenerator.CreateAsync();
                }
            }
            finally { Lock.Release(); }
        }

        var kind = (req.Str("kind") ?? "detailed").ToLowerInvariant() switch
        {
            "brief" => ImageDescriptionKind.BriefDescription,
            "diagram" => ImageDescriptionKind.DiagramDescription,
            "accessible" => ImageDescriptionKind.AccessibleDescription,
            _ => ImageDescriptionKind.DetailedDescription,
        };

        using var buf = await ImageUtil.FromBase64Async(b64, 1600);
        var result = await _gen!.DescribeAsync(buf, kind, new ContentFilterOptions());
        var status = result.Status.ToString();
        ctx.Log($"describeImage status={status} len={result.Description?.Length ?? 0}");
        if (string.IsNullOrEmpty(result.Description))
            return R.Fail(req.Id, "No description (status: " + status + ")" +
                (status.Contains("TooMuchText") ? ". The picture is mostly text: use OCR." : ""));
        var r = R.Ok(req.Id, result.Description);
        r["status"] = status;
        return r;
    }
}
